factorial.code:
MODULE Factorial;
  IMPORT Out;

  PROCEDURE Fact(n: INTEGER): INTEGER;
    VAR r: INTEGER;
  BEGIN
    IF n <= 1 THEN r := 1 ELSE r := n * Fact(n - 1) END
    RETURN r                          (* the one RETURN closes the body *)
  END Fact;

BEGIN
  Out.Int(Fact(10), 0); Out.Ln
END Factorial.

fizzbuzz.code:
MODULE FizzBuzz;
  IMPORT Out;
  VAR i: INTEGER;
BEGIN
  FOR i := 1 TO 15 DO
    IF i MOD 15 = 0 THEN Out.String("FizzBuzz")
    ELSIF i MOD 3 = 0 THEN Out.String("Fizz")
    ELSIF i MOD 5 = 0 THEN Out.String("Buzz")
    ELSE Out.Int(i, 0)
    END;
    Out.Ln
  END
END FizzBuzz.

higher-order.code:
MODULE MapFilter;
  IMPORT Out;

  TYPE
    Predicate = PROCEDURE (x: INTEGER): BOOLEAN;   (* procedure types *)
    Mapping = PROCEDURE (x: INTEGER): INTEGER;

  VAR xs: ARRAY 10 OF INTEGER; i: INTEGER;

  PROCEDURE IsEven(x: INTEGER): BOOLEAN; RETURN ~ODD(x) END IsEven;
  PROCEDURE Square(x: INTEGER): INTEGER; RETURN x * x END Square;

  (* Open array parameter: any length; LEN gives it. Value arrays are read-only. *)
  PROCEDURE FilterMap(a: ARRAY OF INTEGER; keep: Predicate; f: Mapping);
    VAR i: INTEGER; first: BOOLEAN;
  BEGIN
    first := TRUE;
    FOR i := 0 TO LEN(a) - 1 DO
      IF keep(a[i]) THEN
        IF ~first THEN Out.Char(" ") END;
        Out.Int(f(a[i]), 0); first := FALSE
      END
    END;
    Out.Ln
  END FilterMap;

BEGIN
  FOR i := 0 TO 9 DO xs[i] := i + 1 END;
  FilterMap(xs, IsEven, Square)
END MapFilter.

shapes.code:
MODULE Shapes;
  IMPORT Out;

  TYPE
    Shape = POINTER TO ShapeDesc;
    ShapeDesc = RECORD
      area: PROCEDURE (s: Shape): INTEGER        (* a "method": a procedure-typed field *)
    END;
    Rectangle = POINTER TO RECORD (ShapeDesc) width, height: INTEGER END;  (* type extension *)
    Triangle = POINTER TO RECORD (ShapeDesc) base, height: INTEGER END;

  VAR r: Rectangle; t: Triangle;

  PROCEDURE RectArea(s: Shape): INTEGER;
    RETURN s(Rectangle).width * s(Rectangle).height    (* s(T) is a checked type guard *)
  END RectArea;

  PROCEDURE TriArea(s: Shape): INTEGER;
    RETURN s(Triangle).base * s(Triangle).height DIV 2
  END TriArea;

  PROCEDURE Show(name: ARRAY OF CHAR; s: Shape);
  BEGIN
    Out.String(name); Out.String(": "); Out.Int(s.area(s), 0); Out.Ln
  END Show;

BEGIN
  NEW(r); r.width := 3; r.height := 4; r.area := RectArea;
  NEW(t); t.base := 10; t.height := 3; t.area := TriArea;
  Show("Rectangle", r); Show("Triangle", t)
END Shapes.

signature.code:
MODULE Messages;
  IMPORT Out;

  TYPE
    Msg = RECORD END;                              (* an empty base type... *)
    DrawMsg = RECORD (Msg) END;                    (* ...extended by new message types *)
    MoveMsg = RECORD (Msg) dx, dy: INTEGER END;
    Figure = RECORD x, y: INTEGER END;

  VAR fig: Figure; draw: DrawMsg; move: MoveMsg;

  (* One handler takes every message, even kinds added by later modules. *)
  PROCEDURE Handle(VAR f: Figure; VAR m: Msg);
  BEGIN
    IF m IS MoveMsg THEN                           (* run-time type test *)
      INC(f.x, m(MoveMsg).dx); INC(f.y, m(MoveMsg).dy)   (* type guard *)
    ELSIF m IS DrawMsg THEN
      Out.String("figure at "); Out.Int(f.x, 0); Out.Char(","); Out.Int(f.y, 0); Out.Ln
    END                                            (* other messages are ignored *)
  END Handle;

BEGIN
  fig.x := 1; fig.y := 2;
  Handle(fig, draw);
  move.dx := 3; move.dy := 4; Handle(fig, move);
  Handle(fig, draw)
END Messages.
